mapper.sql:
WHERE t.delete_yn = 'N'
AND t.use_yn = #{search.useYn}
AND (t.template_code LIKE CONCAT('%', #{search.keyword}, '%') OR t.template_name LIKE CONCAT('%', #{search.keyword}, '%') OR t.layout_path LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT COUNT(1)
  FROM tb_template
 WHERE template_code = #{templateCode}
   AND delete_yn     = 'N'

  AND template_id <> #{excludeTemplateId}
